package org.apache.commons.math3.geometry.euclidean.twod;

import org.apache.commons.math3.geometry.partitioning.BSPTree;
import org.apache.commons.math3.geometry.partitioning.Region;
import org.apache.commons.math3.geometry.partitioning.RegionFactory;
import org.apache.commons.math3.geometry.euclidean.oned.Euclidean1D;
import org.apache.commons.math3.geometry.euclidean.twod.Euclidean2D;
import org.apache.commons.math3.geometry.euclidean.twod.Vector2D;
import org.junit.Assert;
import org.junit.Test;

public class AgentBRT_Math_32_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Create a BSPTree with no cut and attribute set to true
        BSPTree<Euclidean2D> tree = new BSPTree<>(null, null, null, Boolean.TRUE);

        // Create a PolygonsSet with this tree
        PolygonsSet polygonsSet = new PolygonsSet(tree);

        // Compute geometrical properties
        polygonsSet.computeGeometricalProperties();

        // Check the size and barycenter
        // In the buggy version, this will not be set to infinity and NaN
        Assert.assertEquals(Double.POSITIVE_INFINITY, polygonsSet.getSize(), 0);
        Vector2D barycenter = (Vector2D) polygonsSet.getBarycenter();
        Assert.assertTrue(Double.isNaN(barycenter.getX()));
        Assert.assertTrue(Double.isNaN(barycenter.getY()));
    }
}

